function createBaseDiffInfo(): DiffInfo {
  return { diffUrl: undefined, baseUrl: undefined, extra: "" };
}

export const DiffInfo: MessageFns<DiffInfo> = {
  encode(message: DiffInfo, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.diffUrl !== undefined) {
      UrlDataStruct.encode(message.diffUrl, writer.uint32(10).fork()).join();
    }
    if (message.baseUrl !== undefined) {
      UrlDataStruct.encode(message.baseUrl, writer.uint32(18).fork()).join();
    }
    if (message.extra !== "") {
      writer.uint32(26).string(message.extra);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): DiffInfo {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseDiffInfo();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.diffUrl = UrlDataStruct.decode(reader, reader.uint32());
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.baseUrl = UrlDataStruct.decode(reader, reader.uint32());
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.extra = reader.string();
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },
};

